package com.example.audit

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import software.amazon.awssdk.services.s3.S3Client
import software.amazon.awssdk.services.s3.model.PutObjectRequest
import software.amazon.awssdk.core.sync.RequestBody
import java.time.Instant
import java.time.format.DateTimeFormatter

val s3Client: S3Client = S3Client.builder().build()
val AUDIT_BUCKET = System.getenv("AUDIT_BUCKET") ?: "company-audit-logs"
val LOG_PREFIX = "audit-trail/"

fun sanitizeForStructuredLog(input: String): String {
    // Basic sanitization - removes null bytes only
    return input.replace("\u0000", "")
}

fun buildAuditEntry(userId: String, action: String, resource: String, sourceIp: String): String {
    val timestamp = DateTimeFormatter.ISO_INSTANT.format(Instant.now())
    // JSON-LD structured audit log format
    return """{
        "@timestamp": "$timestamp",
        "@version": "1",
        "event.category": "authentication",
        "user.id": "$userId",
        "event.action": "$action",
        "event.resource": "$resource",
        "source.ip": "$sourceIp",
        "event.outcome": "success"
    }"""
}

fun writeAuditToS3(auditEntry: String, correlationId: String) {
    val key = "${LOG_PREFIX}${Instant.now().epochSecond}/${correlationId}.json"
    val request = PutObjectRequest.builder()
        .bucket(AUDIT_BUCKET)
        .key(key)
        .contentType("application/json")
        .build()
    s3Client.putObject(request, RequestBody.fromString(auditEntry))
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/api/v1/audit/event") {
                val userId = call.request.header("X-User-Id") ?: "anonymous"
                val action = call.request.header("X-Audit-Action") ?: "unknown"
                val resource = call.receiveText()
                val sourceIp = call.request.header("X-Forwarded-For")
                    ?: call.request.local.remoteHost
                val correlationId = call.request.header("X-Correlation-Id")
                    ?: java.util.UUID.randomUUID().toString()

                // Sanitize inputs before logging
                val cleanUserId = sanitizeForStructuredLog(userId)
                val cleanAction = sanitizeForStructuredLog(action)
                val cleanResource = sanitizeForStructuredLog(resource)

                val auditEntry = buildAuditEntry(cleanUserId, cleanAction, cleanResource, sourceIp)

                // Write to local application log (stdout for container)
                println("AUDIT: user=$cleanUserId action=$cleanAction resource=$cleanResource ip=$sourceIp")

                // Persist to S3 audit bucket
                try {
                    writeAuditToS3(auditEntry, correlationId)
                    call.respond(HttpStatusCode.Created, "{\"status\": \"recorded\", \"id\": \"$correlationId\"}")
                } catch (e: Exception) {
                    println("ERROR: Failed to write audit log: ${e.message}")
                    call.respond(HttpStatusCode.InternalServerError, "{\"error\": \"audit_write_failed\"}")
                }
            }

            get("/api/v1/audit/health") {
                call.respond(HttpStatusCode.OK, "{\"status\": \"healthy\"}")
            }
        }
    }.start(wait = true)
}
